SELECT stddev(diagnoses_icd.seq_num) AS sd_diagnostic_utilization, percentile_cont(0.75) within GROUP (ORDER BY omr.result_value) AS p75_in_hospital_mortality, percentile_cont(0.95) within GROUP (ORDER BY omr.result_value) AS p95_in_hospital_mortality, CAST(COUNT(DISTINCT icustays.hadm_id) AS FLOAT) / NULLIF(COUNT(DISTINCT admissions.hadm_id), 0) AS admissions_to_icu_ratio, AVG(icustays.los) AS average_length_of_stay FROM patients JOIN admissions ON patients.subject_id = admissions.subject_id JOIN icustays ON admissions.hadm_id = icustays.hadm_id JOIN omr ON patients.subject_id = omr.subject_id AND admissions.hadm_id = omr.hadm_id WHERE patients.gender = 'M' AND patients.anchor_age = 95 AND icustays.first_careunit = 'ICU' AND omr.result_name = 'Mortality' AND omr.chartdate BETWEEN (CURRENT_DATE - interval '24 hours') AND CURRENT_DATE AND (SELECT COUNT(DISTINCT subject_id) FROM patients WHERE age >= 90 AND age <= 100 AND gender = 'M' AND sepsis = 'Yes') > 0;